'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var abs = require( '@stdlib/math/base/special/abs' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var EPS = require( '@stdlib/constants/float32/eps' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var tryRequire = require( '@stdlib/utils/try-require' );


// FIXTURES //

var mediumPositive = require( './fixtures/medium_positive.json' );
var smallPositive = require( './fixtures/small_positive.json' );
var smallNegative = require( './fixtures/small_negative.json' );
var mediumNegative = require( './fixtures/medium_negative.json' );
var largePositive = require( './fixtures/large_positive.json' );
var tiny = require( './fixtures/tiny.json' );


// VARIABLES //

var INV_SQRT_PI = 0.56418958; // 1 / sqrt(pi) - float32 precision
var erfcxf = tryRequire( resolve(__dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( erfcxf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof erfcxf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', opts, function test( t ) {
	var y;

	y = erfcxf( NaN );
	t.strictEqual( isnanf( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `Infinity` if `x` is smaller than `-26.7`', opts, function test( t ) {
	var y;

	y = erfcxf( -26.7 );
	t.strictEqual( y, PINF, 'returns expected value' );

	y = erfcxf( -30.0 );
	t.strictEqual( y, PINF, 'returns expected value' );

	y = erfcxf( -35.0 );
	t.strictEqual( y, PINF, 'returns expected value' );

	t.end();
});

tape( 'the function returns `( 1 / sqrt(pi) ) / x` if `x` is larger than `5e7`', opts, function test( t ) {
	var expected;
	var delta;
	var tol;
	var y;
	var x;

	x = 5.0e8;
	y = erfcxf( x );
	expected = float64ToFloat32( INV_SQRT_PI / x );
	if ( y === expected ) {
		t.strictEqual( y, expected, 'returns expected value' );
	} else {
		delta = abs( expected - y );
		tol = EPS * abs( expected ); // Standard tolerance
		t.ok( delta <= tol, 'within tolerance. returns '+y+' when provided '+x+'. expected: '+expected+'. delta: '+delta+'. tol: ' +tol+'.' );
	}

	x = 5.0e9;
	y = erfcxf( x );
	expected = float64ToFloat32( INV_SQRT_PI / x );
	if ( y === expected ) {
		t.strictEqual( y, expected, 'returns expected value' );
	} else {
		delta = abs( expected - y );
		tol = (1e-16 + (abs( expected ) * 1e-16)); // Small tolerance for C precision differences
		t.ok( delta <= tol, 'within tolerance. returns '+y+' when provided '+x+'. expected: '+expected+'. delta: '+delta+'. tol: ' +tol+'.' );
	}

	x = 5.0e15;
	y = erfcxf( x );
	expected = float64ToFloat32( INV_SQRT_PI / x );
	if ( y === expected ) {
		t.strictEqual( y, expected, 'returns expected value' );
	} else {
		delta = abs( expected - y );
		tol = (1e-20 + (abs( expected ) * 1e-20)); // Small tolerance for C precision differences
		t.ok( delta <= tol, 'within tolerance. returns '+y+' when provided '+x+'. expected: '+expected+'. delta: '+delta+'. tol: ' +tol+'.' );
	}

	t.end();
});

tape( 'the function computes the scaled complementary error function for positive medium numbers', opts, function test( t ) {
	var expected;
	var delta;
	var tol;
	var x;
	var y;
	var i;
	var e;

	expected = mediumPositive.expected;
	x = mediumPositive.x;
	for ( i = 0; i < expected.length; i++ ) {
		y = erfcxf( x[ i ] );
		e = float64ToFloat32( expected[ i ] );
		if ( y === e ) {
			t.strictEqual( y, e, 'returns '+y+' when provided '+x[i]+'.' );
		} else {
			delta = abs( e - y );
			tol = EPS * abs( e ); // Standard tolerance
			t.ok( delta <= tol, 'within tolerance. returns '+y+' when provided '+x[i]+'. expected: '+e+'. delta: '+delta+'. tol: ' +tol+'.' );
		}
	}
	t.end();
});

